// Verifies X-LendLoop-Signature = v1=hex(HMAC_SHA256(LENDLOOP_TO_N8N_SECRET, `${timestamp}.${rawBody}`))
// over the RAW request body, rejects stale timestamps (replay window), compares in constant time.
const crypto = require('crypto');
const secret = $env.LENDLOOP_TO_N8N_SECRET;
const MAX_SKEW_SECONDS = 300;

const item = $input.first();
const headers = item.json.headers || {};
const ts = String(headers['x-lendloop-timestamp'] || '');
const sig = String(headers['x-lendloop-signature'] || '');

let reason = null;
let event = null;
if (!secret) reason = 'LENDLOOP_TO_N8N_SECRET is not configured';
else if (!/^\d{1,12}$/.test(ts) || !sig) reason = 'missing signature headers';
else if (Math.abs(Date.now() / 1000 - Number(ts)) > MAX_SKEW_SECONDS) reason = 'timestamp outside tolerance';
else {
  const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
  const expected = Buffer.from('v1=' + crypto.createHmac('sha256', secret).update(`${ts}.${raw}`).digest('hex'));
  const given = Buffer.from(sig);
  if (expected.length !== given.length || !crypto.timingSafeEqual(expected, given)) reason = 'signature mismatch';
  else event = JSON.parse(raw);
}
if (reason) console.warn(`[lendloop] rejected webhook: ${reason}`);

// Only the verified, parsed event continues downstream (no headers, no raw body).
return [{ json: { valid: reason === null, reason, event } }];

// Builds the message from the minimal payload Convex sent (first names, the recipient's
// own email, tool name and dates). Nothing else is available to this workflow.
const out = [];
for (const { json } of $input.all()) {
  const e = json.event;
  const tool = e.loan.toolName;
  const who = e.counterpartyName;
  const dates = `${e.loan.startDate} to ${e.loan.endDate}`;
  const asLender = e.recipient.role === 'lender';
  const templates = {
    'loan.requested': [`${who} wants to borrow your ${tool}`,
      `${who} asked to borrow your ${tool} (${dates}). You can approve or decline the request in LendLoop.`],
    'loan.approved': [`Approved: ${tool}`,
      `Good news! ${who} approved your request to borrow the ${tool} (${dates}). Coordinate the pickup with them.`],
    'loan.declined': [`Request declined: ${tool}`,
      `Your request to borrow the ${tool} (${dates}) wasn't approved this time. Other neighbors may have one to lend.`],
    'loan.cancelled': asLender
      ? [`Request cancelled: ${tool}`, `${who} cancelled their request to borrow your ${tool} (${dates}).`]
      : [`Booking cancelled: ${tool}`, `Your booking for the ${tool} (${dates}) was cancelled because the listing was removed.`],
    'loan.returned': [`Returned: ${tool}`,
      `${who} confirmed the ${tool} is back. Thanks for being a great neighbor!`],
  };
  const [subject, body] = templates[e.type] || [`Update on ${tool}`, `There is an update on the loan of ${tool}.`];
  const link = e.link ? `\n\nOpen LendLoop: ${e.link}` : '';
  out.push({ json: {
    eventId: e.eventId,
    type: e.type,
    name: e.recipient.name,
    to: e.recipient.email || null,
    subject: `[LendLoop] ${subject}`,
    text: `Hi ${e.recipient.name},\n\n${body}${link}\n\n- LendLoop`,
  }});
}
return out;

// Fallback channel when the recipient has no email on file: a logged mock notification.
console.log(`[lendloop:mock-notify] ${$json.type} -> ${$json.name}: ${$json.subject}`);
return { json: { ...$json, channel: 'log' } };

const err = $json.error;
const message = String((err && (err.message || err.description)) || err || 'send failed').slice(0, 300);
return { json: { type: 'notification.result', eventId: $('Compose message').item.json.eventId, status: 'failed', error: message } };

// Signs the request body for Convex: v1=hex(HMAC_SHA256(N8N_TO_LENDLOOP_SECRET, `${timestamp}.${body}`)).
// The secret is read from the environment and never appears in the workflow JSON.
const crypto = require('crypto');
const secret = $env.N8N_TO_LENDLOOP_SECRET;
if (!secret) throw new Error('N8N_TO_LENDLOOP_SECRET is not configured');
const body = JSON.stringify($json);
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = 'v1=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');
return { json: { body, timestamp, signature } };
